def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 100:
        return 'C'

    opp_c = 0
    my_c = 0
    my_score = 0
    opp_score = 0
    for a, b in history:
        if b == 'C':
            opp_c += 1
        if a == 'C':
            my_c += 1
        if a == 'C' and b == 'C':
            my_score += 3
            opp_score += 3
        elif a == 'C' and b == 'D':
            opp_score += 5
        elif a == 'D' and b == 'C':
            my_score += 5
        else:
            my_score += 1
            opp_score += 1

    last_me, last_opp = history[-1]
    rounds_left = 100 - n
    opp_rate = opp_c / n

    recent_len = min(8, n)
    recent_opp_c = 0
    for i in range(n - recent_len, n):
        if history[i][1] == 'C':
            recent_opp_c += 1
    recent_opp_rate = recent_opp_c / recent_len

    def_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            def_streak += 1
        else:
            break

    if n == 1:
        return 'C' if last_opp == 'C' else 'C'

    if rounds_left <= 1:
        if last_opp == 'C':
            return 'D'
        return 'D'

    if rounds_left <= 4:
        if recent_opp_rate >= 0.75:
            return 'C' if last_opp == 'C' else 'D'
        if last_opp == 'D':
            return 'D'
        if recent_opp_rate <= 0.25:
            return 'D'
        return 'C'

    if opp_rate >= 0.9 and recent_opp_rate >= 0.75:
        if rounds_left > 10 and n % 19 == 0 and rng.random() < 0.10:
            return 'D'
        return 'C'

    if opp_rate <= 0.2:
        if def_streak >= 2:
            return 'D'
        if rng.random() < 0.10:
            return 'C'
        return 'D'

    if def_streak >= 3:
        if recent_opp_rate >= 0.5:
            return 'D'
        if rng.random() < 0.08:
            return 'C'
        return 'D'

    if last_opp == 'D':
        if def_streak == 1 and recent_opp_rate >= 0.6:
            return 'C'
        if opp_rate >= 0.7:
            return 'C'
        if def_streak == 1:
            if rng.random() < 0.35:
                return 'C'
            return 'D'
        if recent_opp_rate >= 0.5 and rng.random() < 0.3:
            return 'C'
        return 'D'

    if last_opp == 'C':
        if my_score + 6 < opp_score and recent_opp_rate < 0.6 and rounds_left > 8:
            if rng.random() < 0.25:
                return 'D'
        if recent_opp_rate >= 0.5:
            if rounds_left > 12 and n % 23 == 0 and rng.random() < 0.07:
                return 'D'
            return 'C'
        if opp_rate >= 0.5:
            return 'C'
        if rng.random() < 0.2:
            return 'D'
        return 'C'

    return 'C'
